# D2: second difference acting on mu_0..mu_{N-1} with
# mu_N = 0 and shear BC mu_{N+1} = mu_{N-1}
# Row r holds equation (b) at node i = r+1 (rows 0..N-1 <-> nodes 1..N)
D2 = np.zeros((N, N))
for i in range(1, N - 1):          # nodes 1..N-2: full central stencil
    D2[i - 1, i - 1] += 1.0 / dx**2     # mu_{i-1}
    D2[i - 1, i]     += -2.0 / dx**2    # mu_i
    D2[i - 1, i + 1] += 1.0 / dx**2     # mu_{i+1}
# node N-1: mu_{N-2} - 2 mu_{N-1} + mu_N(=0)
D2[N - 2, N - 2] += 1.0 / dx**2
D2[N - 2, N - 1] += -2.0 / dx**2
# node N: mu_{N-1} - 2 mu_N(=0) + mu_{N+1}(=mu_{N-1}) -> 2 mu_{N-1}
D2[N - 1, N - 1] += 2.0 / dx**2
